import itertools

def solve(M, K):
    best_f = None
    max_g_sum = -1

    def generate_f(index, current_val, remaining_sum, current_f):
        nonlocal best_f, max_g_sum
        if index == M + 1:
            dp = [float('inf')] * (K * M + 1)
            dp[0] = 0
            for _ in range(K):
                new_dp = [float('inf')] * (K * M + 1)
                for i in range(K * M + 1):
                    if dp[i] != float('inf'):
                        for j in range(M + 1):
                            if i + j <= K * M:
                                new_dp[i + j] = min(new_dp[i + j], dp[i] + current_f[j])
                dp = new_dp

            g_sum = sum(dp)
            if g_sum > max_g_sum:
                max_g_sum = g_sum
                best_f = list(current_f)
            return

        for val in range(min(current_val, remaining_sum) + 1):
            current_f.append(val)
            generate_f(index + 1, val, remaining_sum - val, current_f)
            current_f.pop()

    generate_f(0, M, M, [])
    return max_g_sum, best_f

for m in range(2, 9):
    print(f"M={m}, K=2:", solve(m, 2))
for m in range(2, 7):
    print(f"M={m}, K=3:", solve(m, 3))
