import random

def eval_f(f, K, M):
    # f is a list of length M+1
    dp = list(f)
    # pad to K*M + 1
    dp += [float('inf')] * (K * M + 1 - len(dp))

    for _ in range(K - 1):
        new_dp = [float('inf')] * (K * M + 1)
        for i in range(K * M + 1):
            if dp[i] != float('inf'):
                for j in range(M + 1):
                    if i + j <= K * M:
                        new_dp[i + j] = min(new_dp[i + j], dp[i] + f[j])
        dp = new_dp
    return sum(x for x in dp if x != float('inf'))

def local_search(M, K, steps=1000):
    # Start with f = [M//(M+1), ...] which is valid
    best_f = [0] * (M + 1)
    best_f[0] = M
    for i in range(1, M+1):
        if sum(best_f) > M:
            best_f[i-1] -= sum(best_f) - M
            break

    # Actually let's start with a better guess: f(x) = max(0, A - Bx)
    best_val = -1
    for A in range(1, M+1):
        f = []
        for x in range(M+1):
            f.append(max(0, A - x))
        if sum(f) <= M:
            val = eval_f(f, K, M)
            if val > best_val:
                best_val = val
                best_f = list(f)

    return best_val, best_f

for m in [10, 20, 30, 40]:
    val, f = local_search(m, 20)
    # Print non-zero elements of f
    f_non_zero = [x for x in f if x > 0]
    print(f"M={m}, K=20: {val}, {f_non_zero}")
