import random
import math

def eval_f(f, K, M):
    dp = list(f)
    dp += [float('inf')] * (K * M + 1 - len(dp))
    for _ in range(K - 1):
        new_dp = [float('inf')] * (K * M + 1)
        for i in range(K * M + 1):
            if dp[i] != float('inf'):
                for j in range(M + 1):
                    if i + j <= K * M:
                        new_dp[i + j] = min(new_dp[i + j], dp[i] + f[j])
        dp = new_dp
    return sum(x for x in dp if x != float('inf'))

def sa(M, K):
    f = [0]*(M+1)
    best_f = list(f)
    best_val = eval_f(f, K, M)

    T = 10.0
    for step in range(2000):
        new_f = list(f)
        idx = random.randint(0, M)
        delta = random.choice([-1, 1])
        new_f[idx] += delta

        for i in range(1, M+1):
            if new_f[i] > new_f[i-1]:
                new_f[i] = new_f[i-1]
        for i in range(M-1, -1, -1):
            if new_f[i] < new_f[i+1]:
                new_f[i] = new_f[i+1]
        for i in range(M+1):
            if new_f[i] < 0:
                new_f[i] = 0

        if sum(new_f) <= M:
            val = eval_f(new_f, K, M)
            if val >= best_val or random.random() < math.exp((val - best_val) / T):
                f = new_f
                if val > best_val:
                    best_val = val
                    best_f = list(f)
        T *= 0.995
    return best_val, best_f

random.seed(42)
for m in [10, 15, 20]:
    val, f = sa(m, 2)
    print(f"M={m}, K=2: {val}, {[x for x in f if x > 0]}")
for m in [10, 15, 20]:
    val, f = sa(m, 3)
    print(f"M={m}, K=3: {val}, {[x for x in f if x > 0]}")
